INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64350605', 64350605, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN MIDDLE PROGRAMMER PENGEMBANGAN SISTEM INFORMASI KRISNA TINGKAT MENENGAH', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 220500000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Menganalisis dan merancang database serta arsitektur aplikasi untuk fitur baru berdasarkan spesifikasi fungsional pada Sistem Informasi KRISNA, baik Pemerintah Pusat dan Pemerintah Daerah; Melakukan pengkodean (coding) dan implementasi fitur/modul menggunakan bahasa pemrograman, framework, dan teknologi yang telah ditetapkan pada Sistem Informasi KRISNA, baik Pemerintah Pusat dan Pemerintah Daerah; Merancang dan mengimplementasikan API untuk mendukung integrasi data dan fungsi Sistem Informasi KRISNA dan sistem K/L lainnya; Melakukan pengujian pada setiap Sub Sistem KRISNA, baik Pemerintah Pusat dan Pemerintah Daerah, untuk memastikan fungsi sistem berjalan tanpa error (bug); Melakukan perbaikan segera (bug fixing) terhadap error yang ditemukan pada Sistem Informasi KRISNA, baik Pemerintah Pusat dan Pemerintah Daerah; Menerapkan praktik pengkodean yang aman (secure coding) dan berkoordinasi dengan tim keamanan informasi terkait celah keamanan (vulnerability) pada Sistem Informasi KRISNA, baik Pemerintah Pusat dan Pemerintah Daerah; Bekerjasama secara intensif dengan Konsultan Pemrograman lainnya dalam rangka pelaksanaan sinkronisasi perencanaan dan penganggaran Pemerintah Pusat dan Pemerintah Daerah; Mengembangkan integrasi dan interkoneksi Sistem Informasi KRISNA dengan sistem informasi lainnya baik di lingkungan Kementerian PPN/Bappenas ataupun Kementerian/Lembaga lainnya; Menyusun laporan kegiatan sesuai dengan jadwal yang telah ditentukan;', 'Diutamakan Konsultan dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki pendidikan minimal S1 di bidang Ilmu Komputer/Teknik Informatika/Sistem Informasi (dibuktikan dengan ijazah jenjang pendidikan); Pengalaman kerja minimal 3 (tiga) tahun sebagai programmer dalam sistem perencanaan dan penganggaran, baik berbasis sistem aplikasi maupun non aplikasi (dibuktikan dengan surat referensi/kontrak kerja) Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS atau Pagu Anggaran (dibuktikan dengan surat referensi/kontrak kerja) Memiliki kemampuan yang baik dan berpengalaman dalam menganalisis, merancang, serta membangun Sistem Informasi Perencanaan dan Penganggaran, serta memiliki pengalaman berkoordinasi dengan stakeholders terkait baik Pemerintah Pusat dan Pemerintah Daerah (dibuktikan dengan Portofolio (Laporan pekerjaan atau screenshot aplikasi) dan/atau sertifikasi keahlian (SKA/Sertifikat Kompetensi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1481274);
