INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64351357', 64351357, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN JUNIOR PROGRAMMER PENGEMBANGAN DASHBOARD CAKRA', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 182000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Merancang interkoneksi data dari sistem KRISNA ke Dashboard Cakra Merancang tampilan program (programmer akan membuat sketsa alur aplikasi, kemudian membuat tampilan grafis); Menulis kode program (memindahkan grafis bentuk flowchart menjadi kode program); Mendefinisikan kebutuhan (menentukan jenis platform serta tools yang akan dibuat sesuai keinginan user); Melakukan debug program (mengecek jika terjadi kesalahan atau error pada suatu aplikasi); Menguji program yang telah dibuat, agar aplikasi yang dibuat bisa bermanfaat untuk user.', 'Diutamakan Konsultan dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); Memiliki pendidikan minimal S1 di bidang Ilmu Komputer/Teknik Informatika/Sistem Informasi (dibuktikan dengan ijazah jenjang pendidikan); Pengalaman kerja minimal 2 tahun sebagai programmer dalam sistem perencanaan dan penganggaran, baik berbasis sistem aplikasi maupun non aplikasi (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak (dibuktikan dengan surat referensi/kontrak kerja); Memiliki pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS atau Pagu Anggaran (dibuktikan dengan surat referensi/kontrak kerja) Memiliki kemampuan yang baik dan berpengalaman dalam menganalisis, merancang, serta membangun Sistem Informasi Perencanaan dan Penganggaran Pemerintah, pengalaman berkoordinasi dengan stakeholders terkait baik Pemerintah Pusat dan Pemerintah Daerah (dibuktikan dengan Portofolio (Laporan pekerjaan atau screenshot aplikasi) dan/atau sertifikasi keahlian (SKA/Sertifikat Kompetensi)).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1482833);
